fn status_for(err: &str) -> u16 {
    match err {
        "NotFound" => 404,
        "Validation" => 422,
        "Conflict" => 409,
        _ => 500,
    }
}

fn main() {
    for e in ["NotFound", "Validation", "Conflict", "Internal"] {
        println!("{} -> {}", e, status_for(e));
    }
}
